  // history
  'history.eyebrow': 'Historija',
  'history.name.title': 'Kako je grad dobio ime',
  'history.name.html': 'Ime dolazi od rijeke Sane, od latinskog <em>sana</em> („zdrava“), kao u <em>Aqua Sana</em>. Godine 1717, u osmanskom periodu, utvrđeni grad spominje se kao <em>Džisr-i Sana</em> (<em>džisr</em> = most).',
  'history.more': 'Cijela historija, u osam poglavlja',
  'history.centuries': 'Kroz stoljeća',
  'history.word': 'latinski · „zdrava“',
  'history.chain.river': 'rijeka',
  'history.chain.today': 'danas',
  'tl.1.yr': 'od 6. do 3. st. p. n. e.',
  'tl.1': 'Željeznodobno naselje s nekropolom od 176 grobova.',
  'tl.2': 'Prvi spomen Kamengrada, tada posjeda knezova Babonića Blagajskih; područje pripada župi Sana.',
  'tl.3': 'Osmanlije zauzimaju područje. Predanje kaže da je sultan Mehmed Fatih ispod Kamengrada klanjao na otvorenom; na tom mjestu nastala je musala.',
  'tl.4.yr': '16. st.',
  'tl.4': 'Gradi se Hamzibegova džamija (prije 1557).',
  'tl.5': 'Austrougarska vojska ulazi u Sanski Most 8. septembra, bez borbe. Grad postaje sjedište kotara i počinje rasti na desnoj obali Sane.',
  'tl.6': 'Ovdje se održava Drugo zasjedanje ZAVNOBiH-a, na kojem je donesena Deklaracija o pravima građana Bosne i Hercegovine.',
  'tl.7': 'Nakon što Vojska Republike Srpske preuzme kontrolu nad općinom, nesrpski civili su ubijani i zatvarani u logore; ubijeni stanovnici kasnije su pronalaženi u oko 30 masovnih grobnica. Na mostu u Vrhpolju 31. maja ubijeni su civili iz sela Begići; u junu je srušena Hamzibegova džamija.',
  'tl.8': 'Armija RBiH ulazi u grad u operaciji Sana 95, 9. i 10. oktobra. Taj dan, 10. oktobar, Sanski Most obilježava kao Dan oslobođenja i Dan općine.',
  'tl.9': 'Hamzibegova džamija ponovo je otvorena nakon obnove.',
  'tl.f.mulez': 'Mulež',
  'tl.f.hamz': 'Hamzibegova džamija danas',
  'tl.f.zav': 'Zgrada Sokolskog doma u knjizi',
  'tl.17': 'U septembru se na Muležu otvara via ferrata, na stijeni visokoj 90 m.',
  'tl.16': 'Sana ponovo plavi grad; kroz ulice se prolazi čamcem.',
  'tl.15': 'Prema popisu, općina ima 62.102 stanovnika i deseta je po broju stanovnika od stotinu općina u Bosni i Hercegovini.',
  'tl.14': 'Građani i općina grade Sokolski dom, a preko Sane već stoji novi, betonski gradski most.',
  'tl.13': 'Osnovan je NK Sana. Prvu nogometnu loptu u grad je 1913. donio Branko Juzbašić, student u Pragu.',
  'tl.12': 'Povelja kralja Bele IV najstariji je poznati dokument koji imenuje Sanu, uz župe Dubicu, Mren i Vrbašku.',
  'tl.11': 'Ovim krajem žive Mezeji, ilirski narod. Rimljani ih pokoravaju i između Sane i Japre uređuju rudarski distrikt.',
  'tl.11.yr': 'Antika',
  'tl.10': 'U Hrustovačkoj pećini žive ljudi vučedolske kulture. Nalazi su toliko osobeni da arheolozi govore o posebnom, hrustovačkom tipu te kulture.',
  'tl.10.yr': 'oko 2600. p. n. e.',

