  // history page (historija.html)
  'hist.meta': 'Historija Sanskog Mosta od prahistorije do danas, u osam poglavlja i sa starim fotografijama.',
  'hist.eyebrow': 'Historija',
  'hist.title.html': 'Pet hiljada godina<br>uz Sanu',
  'hist.lead': 'Od pećine u Hrustovu do grada uz most: kratka historija Sanskog Mosta u osam poglavlja, sa starim fotografijama.',
  'hist.hero.cap': 'Sanski Most, stara fotografija',
  'hist.hero.from': 'od',
  'hist.hero.from.v': '~2600. <small>p. n. e.</small>',
  'hist.hero.ch': 'poglavlja',
  'hist.hero.start': 'Počnite čitati',
  'hist.chapters': 'Poglavlja',
  'hist.src.book': 'Iz knjige „Sanski Most nekad i sad“',
  'hist.sources': 'Izvori',
  'hist.src.census.html': "Institut za istoriju, <a href=\"https://prilozi.iis.unsa.ba/wp-content/uploads/2023/05/prilozi_35.pdf\">Prilozi 35</a>. Podaci o stanovništvu grada prema popisima 1910. i 1921.",
  'hist.src.1.html': "<a href=\"hodnik#zukanovic\">Jasmin Zukanović</a>, <em>Sanski Most nekad i sad</em>. Izvor za većinu starih fotografija u ovim poglavljima.",
  'hist.1.chip': 'Prahistorija',
  'hist.1.title': 'Prvi stanovnici',
  'hist.1.yr.html': '~2600<br>pr. n. e.',
  'hist.1.p1': 'U Hrustovačkoj pećini, oko 12 km od grada, živjeli su ljudi vučedolske kulture. Nalazi iz nje dovoljno su osobeni da arheolozi govore o posebnom, hrustovačkom tipu te kulture, raširenom dolinama Sane i Une.',
  'hist.1.p2': 'Hrustovački tip datira se u kasno bakarno doba, oko 2600-2500. godine prije nove ere. Nalazi se čuvaju u Zemaljskom muzeju u Sarajevu, a pećina je nacionalni spomenik Bosne i Hercegovine.',
  'hist.1.p3': 'Mnogo kasnije ovim krajem žive Mezeji, ilirski narod koji rimski pisci smještaju između Sane i Vrbasa. Njihovo rudarsko središte Splonum bilo je negdje na Sani, ali još nije pronađeno. Rimljani su ih pokorili, stanovnike s utvrđenih gradina naselili u doline, a između Sane i Japre uredili rudarski distrikt.',
  'hist.1.f.map': 'Područje vučedolske kulture',
  'hist.1.f.cave': 'Hrustovačka pećina danas',
  'hist.src.site': 'Fotografija sa stranice mjesta',
  'hist.1.n1': 'od grada do Hrustovačke pećine',
  'hist.1.n2': 'godina prije nove ere: hrustovački tip vučedolske kulture',
  'hist.1.n3': 'mezejsko rudarsko središte „na Sani“, još nepronađeno',
  'hist.see.place': 'Pogledajte mjesto →',
  'hist.2.chip': 'Srednji vijek',
  'hist.2.title': 'Župe Sana i Mren',
  'hist.2.yr.html': '1374',
  'hist.2.p1': 'Prije dolaska Osmanlija ovaj kraj pripada dvjema srednjovjekovnim župama, Sani i Mrenu. Grad Mren bio je središte svoje župe, ali s osmanskim osvajanjem nestaje iz izvora.',
  'hist.2.p2': 'Kamengrad, tvrđava na strmom brdu iznad Blihe, prvi put se spominje 1374. Tada je bio posjed knezova Babonića Blagajskih.',
  'hist.2.f.map': 'Župe Sana i Mren prije dolaska Osmanlija',
  'hist.src.kres': 'Karta prema H. Kreševljakoviću (1958)',
  'hist.2.f.kamengrad': 'Kamengrad danas',
  'hist.src.2.html': 'Hamdija Kreševljaković, „Kamengrad“, <em>Naše starine</em> VI (1958): karta župa Sana i Mren.',
  'hist.3.chip': 'Osmanski period',
  'hist.3.title': 'Musala, most i džamija',
  'hist.3.yr.html': '1498<br>do 1878',
  'hist.3.p1': 'Kamengrad pada pod osmansku vlast krajem 15. vijeka. Predanje kaže da je sultan Mehmed Fatih ispod tvrđave klanjao na otvorenom; na tom mjestu nastala je musala, jedna od rijetkih na Balkanu.',
  'hist.3.p2': 'Uz most na Sani nastaje utvrđeno naselje, u izvorima Džisr-i Sana („most na Sani“), po kojem grad nosi ime. S njegove kapije sačuvana je kamena ploča s natpisom. Osmanlije grade i mostove na Sani kod Tomine i Trnove; preko ostalih rijeka i potoka karavani su uglavnom prelazili gazom.',
  'hist.3.p3': 'Nakon što Osmanlije krajem 17. vijeka izgube Ugarsku i Liku, u Krajinu dolaze muslimanske porodice iz tih krajeva. Neke porodice oko Sanskog Mosta, poput Budimlića, vode porijeklo iz Ugarske, a mnoga krajiška prezimena i danas postoje u Lici.',
  'hist.3.f.musala': '„Musalla“ sultana Fatih Mehmeda II., Donji Kamengrad',
  'hist.src.postcard': 'Stara razglednica',
  'hist.3.f.grad': 'Sana i stari dio grada, kolorirana fotografija',
  'hist.3.f.ploca': 'Kamena ploča sa zapadne strane kapije Sane',
  'hist.3.tn': 'Hamzibegova džamija 1946, s jednom munarom, i danas, obnovljena 2000.',
  'hist.4.chip': 'Austro-Ugarska',
  'hist.4.title': 'Selo postaje varošica',
  'hist.4.yr.html': '1878<br>do 1918',
  'hist.4.p1': 'Austrougarska vojska ulazi u Sanski Most 8. septembra 1878, bez borbe, nakon dvodnevnih borbi za Ključ. Novi grad počinje rasti na desnoj obali Sane.',
  'hist.4.p2': 'Grade se zgrada kotara, kotarski sud, žandarmerija i gruntovnica, a otvaraju se prva apoteka i prve osnovne škole, u Sanskom Mostu i Starom Majdanu. Makadamski put od Prijedora preko Sanskog Mosta do Ključa, dug 78 km, počinje se graditi 1879. Podgrmečka cesta prema Lušci Palanci i Bosanskoj Krupi gradi se od 1882. do 1894, a kasnije i uskotračna pruga prema Drvaru.',
  'hist.4.p3': 'Dana 18. augusta 1915. otkriven je spomenik caru Franji Josipu I, podignut troškom građana i seljaka cijelog kotara. Tadašnje novine pisale su da je to prvi carski spomenik u Bosni i Hercegovini. Nova vlast srušila ga je već u decembru 1918.',
  'hist.4.f.spomenik': 'Otkrivanje spomenika, 18. august 1915.',
  'hist.src.paper': 'Iz tadašnjih novina, prema knjizi „Sanski Most nekad i sad“',
  'hist.4.f.novine': 'Novinski izvještaj o otkrivanju spomenika',
  'hist.4.bars': 'Stanovnika u varoši Sanski Most, prema popisima',
  'hist.4.bars.note': 'U cijelom kotaru 1879. je živjelo 18 371 stanovnika, a 1910. već 38 422.',
  'hist.5.chip': '20. vijek',
  'hist.5.title': 'Lopta, Sokolski dom i novi most',
  'hist.5.yr.html': '1913<br>do 1971',
  'hist.5.p1': 'Prvu nogometnu loptu donio je u Sanski Most krajem jula 1913. Branko Juzbašić, student u Pragu i sin gradskog ljekara. Stariji mještani nisu bili oduševljeni mladićima koji satima trče za loptom, a Prvi svjetski rat prekinuo je igru. Godine 1922. osnovan je NK Sana.',
  'hist.5.p2': 'Godine 1939. građani i općina grade Sokolski dom, među prvima takve vrste u Bosni i Hercegovini. U njemu je 1944, na Drugom zasjedanju ZAVNOBiH-a, donesena Deklaracija o pravima građana Bosne i Hercegovine. Zgrada je 1995. zapaljena, a zatim srušena.',
  'hist.5.p3': 'Iste 1939. preko Sane je već stajao novi, betonski gradski most. Prema popisu iz 1971, općina Sanski Most imala je 62.102 stanovnika i bila je deseta po broju stanovnika od tadašnjih stotinu općina u Bosni i Hercegovini.',
  'hist.5.f.fudbal': 'Jedna od prvih sanskih nogometnih ekipa (kolorirano)',
  'hist.5.f.dom': 'Sokolski dom, izgrađen 1939.',
  'hist.5.f.most': 'Pogled s novog betonskog mosta prema Mahali i Hamzibegovoj džamiji, novembar 1939.',
  'hist.5.f.avion': 'Saveznički avion u Krkojevcima, 1944.',
  'hist.5.n1': 'prva nogometna lopta u gradu',
  'hist.5.n2': 'osnovan NK Sana',
  'hist.5.n3': 'općina u BiH po broju stanovnika 1971.',
  'hist.src.3.html': 'Tehvid Jakupović, <em>60 godina FK Podgrmeč</em> (2004), sjećanja Slave Došena: prva nogometna lopta i prvi klubovi.',
  'hist.6.chip': 'Grad i rijeka',
  'hist.6.title': 'Grad i rijeka',
  'hist.6.yr.html': 'Sana',
  'hist.6.p1': 'Sana je gradu dala ime, ali ga je i plavila. Knjiga „Sanski Most nekad i sad“ bilježi velike poplave od 1956. do danas.',
  'hist.6.p2': "Posljednje otvoreno prvenstvo grada u plivanju održano je 27. jula 1983. Plivalo se niz Sanu od plaže Slap do Gradskog mosta.",
  'hist.6.p3': 'U Sanskom Mostu je 9. jula 1902. izmjereno 44,5 °C. Meteorološka stanica u gradu zabilježila je 17. februara 1956. temperaturu od -30,3 °C.',
  'hist.6.temp.html': '44,5<small>°C</small>',
